  patientItems: Item[] = [{label:'Vue d’ensemble',icon:'⌂',path:''},{label:'Trouver un médecin',icon:'⌕',path:'medecins'},{label:'Mes rendez-vous',icon:'▦',path:'rendez-vous'},{label:'Suivi & historique',icon:'◷',path:'historique'},{label:'Notifications',icon:'♧',path:'notifications'},{label:'Mon profil',icon:'○',path:'profil'},{label:'Paramètres',icon:'⚙',path:'parametres'}];
