  get description() { const map:Record<string,string>={ '':'Voici les informations récentes de votre espace.', medecins:'Recherchez un professionnel selon vos besoins.', approbations:'Examinez les demandes des médecins inscrits.', patients:'Consultez les comptes patients et leur activité de rendez-vous.', 'rendez-vous':'Consultez et gérez les rendez-vous autorisés.', historique:'Retrouvez le suivi et l’historique de vos rendez-vous.', disponibilites:'Gérez vos créneaux de consultation.', absences:'Déclarez une absence et organisez les rendez-vous concernés.', calendrier:'Visualisez votre agenda de consultation.', activite:'Consultez les actions administratives consignées.', notifications:'Retrouvez vos notifications Hello Doc.', profil:'Consultez et mettez à jour vos informations personnelles.', parametres:'Gérez vos préférences de compte.', avis:'Consultez les avis liés à votre activité.', }; return map[this.area] ?? map['']; }
