  get scheduleSummary(){return this.scheduleDays.filter(d=>d.active).map(d=>`${d.label} : ${[d.firstEnabled?`${d.firstStart}–${d.firstEnd}`:'',d.secondEnabled?`${d.secondStart}–${d.secondEnd}`:''].filter(Boolean).join(' puis ')}`).join(' · ')||'Aucun jour de consultation configuré.';}
