  load() { this.loading=true; this.error=''; this.errorTitle='Impossible de charger les données'; this.dashboard=null;this.profile=null;this.unavailableMessage='';if(this.role==='ADMIN'&&this.area==='rendez-vous'){this.loading=false;this.unavailableMessage='Le répertoire administratif des rendez-vous sera disponible après la mise en place des rendez-vous (lots 2 et 5).';this.records=[];return;}if(this.role==='ADMIN'&&this.area==='notifications'){this.loading=false;this.unavailableMessage='Les notifications administratives seront disponibles avec le lot 3.';this.records=[];return;}if(this.role==='ADMIN'&&this.area==='activite'){this.loading=false;this.unavailableMessage='Le journal d’activité sera disponible avec le lot 5.';this.records=[];return;}const path=this.endpoint();const query=this.role==='DOCTOR'&&this.area==='calendrier'?{from:new Date(this.monthCursor.getFullYear(),this.monthCursor.getMonth(),1).toISOString(),to:new Date(this.monthCursor.getFullYear(),this.monthCursor.getMonth()+1,1).toISOString()}:undefined; this.api.get<any>(path,query).subscribe({next:data=>{this.loading=false;this.dashboard=(this.area===''||this.area==='dashboard')&&data&&typeof data==='object'&&!Array.isArray(data)?data:null;this.profile=(this.area==='profil'||(this.role==='ADMIN'&&this.area==='parametres'))&&data&&!Array.isArray(data)?data:null;if(this.profile){this.profileForm.patchValue({firstName:data.firstName??'',lastName:data.lastName??'',phone:data.phone??'',address:data.address??'',serviceTitle:data.serviceTitle??'',specialty:data.specialty??'',durationMinutes:data.durationMinutes??30,workStart:data.workStart??'08:00',workEnd:data.workEnd??'17:00',pauseMinutes:data.pauseMinutes??0,location:data.location??data.address??'',description:data.description??''});this.profileDays=(data.workingDays??['1','2','3','4','5']).map(String);this.profileServices.clear();(data.services??[]).forEach((s:any)=>this.addProfileService(s));if(!this.profileServices.length)this.addProfileService();}this.records=Array.isArray(data)?data:Array.isArray(data?.content)?data.content:[];if(this.role==='DOCTOR'&&this.area==='disponibilites')this.initializeSchedule(this.records);},error:e=>{this.loading=false;this.error=e.message;this.records=[];this.dashboard=null;this.profile=null;}}); }
  primaryAction() { if(this.area==='rendez-vous'){this.load();return;} if(this.area==='medecins'){this.searchDoctors();return;} if(this.area==='disponibilites'||this.area==='absences'){document.querySelector('.workspace-form')?.scrollIntoView({behavior:'smooth',block:'center'});return;} }
  searchDoctors() { const q=this.doctorSearch.getRawValue();this.loading=true;this.error='';this.api.get<any>('/doctors',{q:q.q??'',specialty:q.specialty??'',city:q.city??'',availableOn:q.availableOn??'',page:0,size:30}).subscribe({next:r=>{this.records=Array.isArray(r)?r:r?.content??[];this.loading=false;},error:e=>{this.records=[];this.loading=false;this.error=e.message;}}); }
  initializeSchedule(rows:any[]){this.scheduleDays.forEach(day=>{const windows=rows.filter(x=>Number(x.isoWeekday)===day.isoWeekday).sort((a,b)=>String(a.startTime).localeCompare(String(b.startTime)));day.active=windows.length>0;day.firstEnabled=windows.length>0;day.firstStart=String(windows[0]?.startTime??'09:00').slice(0,5);day.firstEnd=String(windows[0]?.endTime??'12:00').slice(0,5);day.secondEnabled=windows.length>1;day.secondStart=String(windows[1]?.startTime??'14:00').slice(0,5);day.secondEnd=String(windows[1]?.endTime??'17:00').slice(0,5);if(windows[0]){this.scheduleDuration=Number(windows[0].slotDurationMinutes)||30;this.schedulePause=Number(windows[0].pauseMinutes)||0;}});this.api.get<any>('/doctors/me').subscribe({next:p=>{this.scheduleDuration=Number(p.durationMinutes)||this.scheduleDuration;this.schedulePause=Number(p.pauseMinutes)||this.schedulePause;}});}
  copyScheduleDay(day:any){for(const target of this.scheduleDays)if(this.copyTargets[target.isoWeekday]){target.active=day.active;target.firstEnabled=day.firstEnabled;target.firstStart=day.firstStart;target.firstEnd=day.firstEnd;target.secondEnabled=day.secondEnabled;target.secondStart=day.secondStart;target.secondEnd=day.secondEnd;}this.copyTargets={};this.copySource=null;}
  saveWeeklyAvailability(){this.scheduleError='';const windows:any[]=[];for(const d of this.scheduleDays){if(!d.active)continue;const dayWindows:any[]=[];if(d.firstEnabled)dayWindows.push({start:d.firstStart,end:d.firstEnd,name:'première'});if(d.secondEnabled)dayWindows.push({start:d.secondStart,end:d.secondEnd,name:'deuxième'});if(dayWindows.length>2){this.scheduleError=`${d.label} : deux plages maximum.`;return;}for(const w of dayWindows){if(!w.start||!w.end||w.end<=w.start){this.scheduleError=`${d.label}, ${w.name} plage : l’heure de fin doit suivre l’heure de début.`;return;}if(Number(w.start.slice(3,5))%5||Number(w.end.slice(3,5))%5){this.scheduleError='Les heures doivent être réglées par pas de 5 minutes.';return;}const mins=(Number(w.end.slice(0,2))*60+Number(w.end.slice(3,5)))-(Number(w.start.slice(0,2))*60+Number(w.start.slice(3,5)));if(mins<Number(this.scheduleDuration)){this.scheduleError=`${d.label}, ${w.name} plage : elle doit contenir au moins un créneau de ${this.scheduleDuration} minutes.`;return;}windows.push({isoWeekday:d.isoWeekday,startTime:w.start,endTime:w.end});}if(dayWindows.length===2&&dayWindows[1].start<=dayWindows[0].end){this.scheduleError=`${d.label} : la deuxième plage doit commencer après la fin de la première.`;return;}}if(!Number.isInteger(Number(this.scheduleDuration))||this.scheduleDuration<5||this.scheduleDuration>240||this.scheduleDuration%5||this.schedulePause<0||this.schedulePause>240){this.scheduleError='La durée doit être comprise entre 5 et 240 minutes par pas de 5; la pause entre 0 et 240 minutes.';return;}this.busy=true;this.api.put('/doctors/me/availabilities/weekly',{slotDurationMinutes:Number(this.scheduleDuration),pauseMinutes:Number(this.schedulePause),windows}).subscribe({next:()=>{this.busy=false;this.notice='Vos horaires hebdomadaires ont été enregistrés.';this.load();},error:e=>{this.busy=false;this.scheduleError=e.message||'Impossible d’enregistrer les horaires.';}});}
  editAvailability(record:any){this.editingAvailabilityId=record.id;this.availabilityForm.patchValue({isoWeekday:String(record.isoWeekday),start:String(record.startTime).slice(0,5),end:String(record.endTime).slice(0,5)});document.querySelector('.workspace-form')?.scrollIntoView({behavior:'smooth',block:'center'});}
