  declareAbsence() { this.absenceForm.markAllAsTouched();const v=this.absenceForm.getRawValue();if(this.absenceForm.invalid||!v.startDate||!v.reason)return;if(v.type==='FULL_DAY'&&(!v.endDate||v.endDate<v.startDate)){this.error='Choisissez une date de fin égale ou postérieure à la date de début.';return;}if(v.type==='PARTIAL'&&(!v.startTime||!v.endTime||v.endTime<=v.startTime)){this.error='Pour une absence partielle, renseignez une heure de fin après le début.';return;}this.busy=true;this.error='';const partial=v.type==='PARTIAL';const body={startDate:v.startDate,endDate:partial?v.startDate:v.endDate,startTime:partial?v.startTime:null,endTime:partial?v.endTime:null,reason:v.reason,comment:v.comment};const request=this.editingAbsenceId?this.api.put(`/doctors/me/absences/${this.editingAbsenceId}`,body):this.api.post('/doctors/me/absences',body);request.subscribe({next:()=>{this.busy=false;this.notice='Absence enregistrée.';this.editingAbsenceId=null;this.absenceForm.reset({type:'FULL_DAY'});this.load();},error:e=>{this.busy=false;this.error=e.message;}}); }
  editAbsence(record:any){this.editingAbsenceId=record.id;this.absenceForm.patchValue({type:record.startTime?'PARTIAL':'FULL_DAY',startDate:record.startDate,endDate:record.endDate,startTime:record.startTime?.slice(0,5)??'',endTime:record.endTime?.slice(0,5)??'',reason:record.reason,comment:record.comment??''});document.querySelector('.workspace-form')?.scrollIntoView({behavior:'smooth',block:'center'});}
  weekdayLabel(iso:number){return this.profileDayOptions.find(x=>Number(x.value)===Number(iso))?.label??`Jour ${iso}`;}
  openRecord(record:any) { if(this.role==='ADMIN'&&this.area==='medecins'){if(record.id)void this.router.navigate(['/admin/medecins',record.id]);return;}if(this.role==='ADMIN'&&['patients','approbations'].includes(this.area)){this.expandedRecordId=this.expandedRecordId===record.id?null:record.id;return;}if(!record.id){this.notice='Les détails de cet élément ne sont pas disponibles.';return;}if(this.role==='PATIENT'&&this.area==='medecins'){void this.router.navigate(['/patient/medecins',record.id]);return;}if(this.role==='DOCTOR'&&this.area==='patients'){void this.router.navigate(['/medecin/patients',record.id]);return;}if(['rendez-vous','historique'].includes(this.area)){void this.router.navigate([this.base,'rendez-vous',record.id]);return;}if(this.role==='DOCTOR'&&this.area==='disponibilites'){this.editAvailability(record);return;}if(this.role==='DOCTOR'&&this.area==='absences'){this.editAbsence(record);return;}this.notice='Les détails de cet élément sont fournis par le service Hello Doc.'; }
  doctorDocumentUrl(record:any){return `${environment.apiBaseUrl}/admin/doctors/${record.id}/document`;}
  decide(record:any, approved:boolean) { if(!record.id)return;this.api.post(`/admin/doctors/${record.id}/${approved?'approve':'reject'}`,approved?{}:{reason:'Demande refusée après examen.'}).subscribe({next:()=>{this.notice=approved?'Demande approuvée.':'Demande refusée.';this.load();},error:e=>this.error=e.message}); }
  deleteAccount(record:any) { if(!record.id)return;const kind=this.area==='patients'?'patient':'médecin';const label=record.fullName||record.name||record.title||record.email||kind;if(!window.confirm(`Supprimer définitivement le compte de ${label} et ses données de profil ? Cette action est irréversible.`))return;const collection=this.area==='patients'?'patients':'doctors';this.busy=true;this.error='';this.errorTitle='Suppression impossible';this.api.delete(`/admin/${collection}/${record.id}`).subscribe({next:()=>{this.busy=false;this.notice=`Le compte ${kind} a été supprimé.`;this.load();},error:e=>{this.busy=false;this.error=e.message||`Impossible de supprimer ce compte ${kind}.`;}}); }
  setActive(record:any,active:boolean) { const collection=this.area==='patients'?'patients':'doctors';if(!record.id)return;this.api.patch(`/admin/${collection}/${record.id}/status`,{status:active?'ACTIVE':'INACTIVE'}).subscribe({next:()=>{this.notice=active?'Compte activé.':'Compte désactivé.';this.load();},error:e=>this.error=e.message}); }
